function validate([chargeTimes, runningCosts, budget]) {
  const n = chargeTimes.length;
  if (n < 1 || n > 50000) return 'chargeTimes needs 1 to 50000 values.';
  if (runningCosts.length !== n) return 'chargeTimes and runningCosts must have the same length.';
  if (chargeTimes.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each charge time is an integer from 1 to 10^5.';
  if (runningCosts.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each running cost is an integer from 1 to 10^5.';
  if (!Number.isInteger(budget) || budget < 1 || budget > 1e15) return 'budget is an integer from 1 to 10^15.';
  return null;
}

