function maximumRobots(chargeTimes, runningCosts, budget) {
  const deque = [];
  let head = 0;
  let left = 0;
  let sum = 0;
  let best = 0;

  for (let right = 0; right < chargeTimes.length; right++) {
    while (deque.length > head && chargeTimes[deque[deque.length - 1]] <= chargeTimes[right]) {
      deque.pop();
    }
    deque.push(right);
    sum += runningCosts[right];

    while (left <= right && chargeTimes[deque[head]] + (right - left + 1) * sum > budget) {
      if (deque[head] === left) {
        head++;
      }
      sum -= runningCosts[left];
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

