function maximumRobots(chargeTimes, runningCosts, budget) {
  const n = chargeTimes.length;
  let best = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      let top = 0, total = 0;
      for (let t = i; t <= j; t++) { top = Math.max(top, chargeTimes[t]); total += runningCosts[t]; }
      const k = j - i + 1;
      if (top + k * total <= budget && k > best) best = k;
    }
  }
  return best;
}

