function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const cost = (charge, run, i, k) => {
    let top = 0, total = 0;
    for (let t = i; t < i + k; t++) { top = Math.max(top, charge[t]); total += run[t]; }
    return top + k * total;
  };
  if (size === 'large') {
    const n = 2000;
    const runTop = rand() < 0.5 ? 100000 : 10;
    const chargeTimes = Array.from({ length: n }, () => int(1, 100000));
    const runningCosts = Array.from({ length: n }, () => int(1, runTop));
    const k = int(1, n);
    const start = int(0, n - k);
    const base = cost(chargeTimes, runningCosts, start, k);
    return [chargeTimes, runningCosts, base + int(0, Math.floor(base / 10))];
  }
  const n = int(1, 8);
  const top = rand() < 0.3 ? 3 : 12;
  const chargeTimes = Array.from({ length: n }, () => int(1, top));
  const runningCosts = Array.from({ length: n }, () => int(1, top));
  const k = int(1, n);
  const start = int(0, n - k);
  const base = cost(chargeTimes, runningCosts, start, k);
  return [chargeTimes, runningCosts, Math.max(1, base + int(-5, 5))];
}
